73	// fakeView stands in for a real view. It implements every optional interface
74	// the router probes for — FormView, FooterView, HeaderView, FilterBarView and
75	// help.Provider — with each answer settable, so a test can build the exact
76	// shape it needs. It records every message forwarded to it, which is how the
77	// tests tell "the view received the key" from "the router consumed it".
78	type fakeView struct {
79		title        string
80		body         string
81		editing      bool
82		filterBar    bool
83		footerHeight int
84		footer       string
85		shortcuts    shortcut.Shortcuts
86		helpContent  help.Content
87	
88		// onKey runs before a key is recorded, so a test can make the view change
89		// shape in response to one — the filter bar opening is the case the router
90		// has to notice.
91		onKey func(*fakeView)
92	
93		inits    int
94		received []tea.Msg
95	}
96	
97	func (v *fakeView) Init() tea.Cmd { v.inits++; return nil }
98	
99	func (v *fakeView) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
100		if key, ok := msg.(tea.KeyPressMsg); ok && v.onKey != nil {
101			_ = key
102			v.onKey(v)
103		}
104		v.received = append(v.received, msg)
105		return v, nil
106	}
107	
108	func (v *fakeView) Render() string                   { return v.body }
109	func (v *fakeView) View() tea.View                   { return tea.NewView(v.Render()) }
110	func (v *fakeView) InEditMode() bool                 { return v.editing }
111	func (v *fakeView) FilterBarVisible() bool           { return v.filterBar }
112	func (v *fakeView) GetFooterHeight() int             { return v.footerHeight }
113	func (v *fakeView) RenderFooter(int) string          { return v.footer }
114	func (v *fakeView) GetShortcuts() shortcut.Shortcuts { return v.shortcuts }
115	func (v *fakeView) GetTitle() string                 { return v.title }
116	func (v *fakeView) GetIcon() string                  { return "" }
117	func (v *fakeView) GetHelpContent() help.Content     { return v.helpContent }
118	func (v *fakeView) GetHeaderInfo(ctx string) []shortcut.HeaderInfo {
119		return []shortcut.HeaderInfo{{Key: "Context", Value: ctx}}
120	}
121	
122	// keysSeen returns the String() of every key the router forwarded.
123	func (v *fakeView) keysSeen() []string {
124		var out []string
125		for _, msg := range v.received {
126			if key, ok := msg.(tea.KeyPressMsg); ok {
127				out = append(out, key.String())
128			}
129		}
130		return out
131	}
