142	// receivedOf reports whether the view was forwarded a message of type T.
143	func receivedOf[T tea.Msg](v *fakeView) (T, bool) {
144		for _, msg := range v.received {
145			if typed, ok := msg.(T); ok {
146				return typed, true
147			}
148		}
149		var zero T
150		return zero, false
151	}
